from admissions_records import *
unknown={'satPolicy':'unknown','note':L('Academic eligibility depends on recognition of the school qualification and programme selection. No universal SAT/ACT exemption is inferred from a language page.','Академический допуск зависит от признания школьной квалификации и отбора программы. Языковая страница не устанавливает универсальное освобождение от SAT/ACT.')}
def s(url,en,ru,pages=None):return S(url,L(en,ru),pages=pages,access='web-pdf-read' if pages else 'web-html-read')
def save(id,routes,change,gaps=None):record(id,routes,change,gaps or ['Fall 2027-specific applicability, school-equivalence assessment and any programme-specific academic examinations remain unconfirmed.'])

u='https://www.hs-anhalt.de/en/degree-programs/ibs.html'
sources=[s(u,'Anhalt International Business BA, Bernburg: two language branches','Anhalt International Business BA, Bernburg: две языковые ветви')]
save('anhalt-university',[route(id='ibs-english',label=L('International Business BA — English branch, Bernburg','International Business BA — английская ветвь, Bernburg'),programmeIds=['business','economics'],english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':6.5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':88}]},'alternatives':L('Cambridge CPE or CAE grades A/B/C. No IELTS section minimum or general MOI waiver is stated in this section. German is studied within the degree.','Cambridge CPE либо CAE с A/B/C. В разделе не указан минимум секций IELTS либо общее освобождение MOI. Немецкий изучается в программе.')},academic=unknown,documents=[L('Recognised higher-education entrance qualification with final grade 3.0 or better in the programme’s German-grade assessment, motivation letter and possible aptitude interview. Do not convert an applicant’s grade scale automatically.','Признанная квалификация допуска с итоговой 3,0 или лучше по немецкой оценке программы, мотивационное письмо и возможное интервью. Шкала кандидата автоматически не пересчитывается.')],sources=sources),route(id='ibs-german',language='de',label=L('International Business BA — German branch, Bernburg','International Business BA — немецкая ветвь, Bernburg'),programmeIds=['business','economics'],localLanguage=[{'name':'German','requirement':L('DSH 2 or TestDaF TDN 4 in all four parts; equivalent certificates may be accepted. This is separate from the English branch’s IELTS 6.5.','DSH 2 либо TestDaF TDN 4 во всех четырёх частях; могут приниматься эквиваленты. Это отдельно от IELTS 6,5 английской ветви.')}],academic=unknown,sources=sources)],'Separated English and German International Business routes with actual Bernburg language evidence.')

u='https://uni-freiburg.de/ucf/las/apply/'
f='https://uni-freiburg.de/en/studies/applying/language-certificates/?set_language=en'
save('university-of-freiburg',[route(id='las',label=L('Liberal Arts and Sciences bachelor — University College Freiburg','Бакалавриат Liberal Arts and Sciences — University College Freiburg'),english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'variant':'IELTS Academic','min':5.5,'role':'admission'},'alternatives':L('LAS requires CEFR B2. The university’s B2 list includes IELTS Academic 5.5–6.5, TOEFL iBT 72–94 or 4.0–4.5, PTE Academic 59–75, Cambridge FCE/CAE/CPE, TOEFL Essentials 8–9.5, UNIcert and named qualifications. These are published level categories, not inferred conversions.','LAS требует CEFR B2. Список B2 вуза включает IELTS Academic 5,5–6,5, TOEFL iBT 72–94 либо 4,0–4,5, PTE Academic 59–75, Cambridge FCE/CAE/CPE, TOEFL Essentials 8–9,5, UNIcert и названные квалификации. Это опубликованные категории уровня, а не предполагаемые пересчёты.'),'waiver':L('English mother tongue or listed nationality, school qualification, IB or completed English-medium degree categories may provide evidence; consult the actual B2 category.','Могут подойти английский как родной либо перечисленные категории гражданства, школьной квалификации, IB или завершённой англоязычной степени; нужна именно категория B2.')},academic=unknown,documents=[L('Recognised entrance qualification, English essay and motivation letter (each at most 500 words), authorship declaration and orientation-procedure evidence. The currently displayed essay prompt is for 2026 and is not reused as a 2027 task.','Признанный допуск, эссе и мотивационное письмо на английском (каждое до 500 слов), декларация авторства и подтверждение ориентационной процедуры. Сейчас показана тема эссе 2026, она не переносится как задание 2027.')],sources=[s(u,'Freiburg LAS application requirements: current 2026 essay context','Freiburg LAS: требования заявки с текущим контекстом эссе 2026'),s(f,'Freiburg accepted B2 English certificates','Freiburg: принимаемые сертификаты английского B2')])],'Anchored LAS to B2 and accepted evidence, not a graduate C1 threshold; kept the 2026 essay context explicit.')

u='https://www.fau.eu/studying/international-students/application-and-enrollment-for-international-applicants/german-language-courses-german-language-proficiency-and-language-certificates/'
save('fau-erlangen-nurnberg',[route(id='german-bachelor',language='de',label=L('German-taught bachelor admission — English exceptions excluded','Немецкоязычный бакалаврский приём — английские исключения не включены'),academic=unknown,localLanguage=[{'name':'German','requirement':L('DSH 2, TestDaF 4 in every part, Goethe C2, ÖSD C2, telc C1 Hochschule/C2 or the listed equivalent qualifications. B2 can permit the pre-study DSH route but does not replace DSH 2 for enrolment. Medical/pharmacy categories need proof already at application.','DSH 2, TestDaF 4 в каждой части, Goethe C2, ÖSD C2, telc C1 Hochschule/C2 либо перечисленные эквиваленты. B2 может допускать маршрут DSH перед учёбой, но не заменяет DSH 2 для зачисления. Для медицинских/фармацевтических категорий доказательство нужно уже при заявке.')}],sources=[s(u,'FAU German bachelor proficiency and English degree exceptions','FAU: немецкий бакалавриата и исключения английских степеней')],note=L('Autonomy Technologies, Clean Energy Processes, International Business Studies, Artificial Intelligence and International Economic Studies are named fully English bachelor exceptions. Their own English/academic entry rules still require programme verification; German DSH is not assigned to them.','Autonomy Technologies, Clean Energy Processes, International Business Studies, Artificial Intelligence и International Economic Studies названы полностью английскими бакалаврскими исключениями. Их английские/академические условия ещё требуют проверки программы; немецкий DSH им не назначается.'))],'Separated German-language enrolment proof from B2 preparation and explicitly excluded the five English bachelor routes.')

