save('technische-hochschule-ingolstadt',[route(id='english-bachelor',label=L('English-main-language bachelor admission — THI programme rules apply','Бакалавриат с основным английским — действуют правила программы THI'),english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':None},'toefl':{'accepted':True,'scales':[{'period':'post2026','min':4}]},'alternatives':L('B2 English required unless a German-language university entrance qualification applies. March 2026 accepted evidence includes TOEFL iBT 4, TOEFL ITP 543, IELTS, Cambridge FCE, PTE Academic B2, UNIcert II, MOTET and specified school/English-degree evidence. The PDF does not give a numerical IELTS cutoff.','Нужен B2 английского, кроме применимой немецкоязычной квалификации допуска. В списке марта 2026 есть TOEFL iBT 4, TOEFL ITP 543, IELTS, Cambridge FCE, PTE Academic B2, UNIcert II, MOTET и указанное школьное/англоязычное образование. Числового порога IELTS в PDF нет.')},academic=unknown,localLanguage=[{'name':'Programme-specific German','requirement':L('Architecture and Sustainable Civil Engineering: German A2 by semester 2 and B2 by semester 5; Engineering and Management: A2 by semester 4. These are progression deadlines, not a universal German entry condition for English degrees.','Architecture и Sustainable Civil Engineering: немецкий A2 к семестру 2 и B2 к семестру 5; Engineering and Management: A2 к семестру 4. Это сроки освоения языка, а не универсальное немецкое условие поступления на английские степени.')}],sources=[s(u,'THI bachelor application: English and later German conditions','THI: бакалаврская заявка, английский и последующие условия немецкого'),s(p,'THI accepted B2 English certificates, March 2026','THI: принимаемые сертификаты английского B2, март 2026',[1,2])])],'Added actual B2 certificate alternatives without inventing an IELTS number or moving later German milestones to admission.')

u='https://uni-koeln.de/en/studium-lehre/international/studium-in-koeln/internationale-bewerbungen/bachelor-studium-staatsexamen/bewerbungsverfahren-fuer-nicht-eu-buergerinnen/application-procedure-for-non-eu-citizens-with-formal-university-entrance-qualification-studienstart-international-integrale'
save('university-of-cologne',[route(id='non-eu-direct-hzb',language='de',label=L('Non-EU applicant with recognised direct university entrance qualification','Кандидат вне ЕС с признанной квалификацией прямого допуска'),academic={'satPolicy':'unknown','note':L('TestAS is required for this non-EU procedure, with core and relevant subject module. Paper/digital accepted; rank thresholds vary by faculty. Nursing/Midwifery dual degrees have named exceptions. SAT/ACT are not established substitutes.','Для этой процедуры вне ЕС требуется TestAS с базовой и соответствующей предметной частью. Принимаются бумажный/digital; пороги процентилей зависят от факультета. У двойных Nursing/Midwifery названные исключения. SAT/ACT не подтверждены как замены.')},localLanguage=[{'name':'German','requirement':L('DSH 2; TestDaF TDN4 in all parts; DSD II; telc C1 Hochschule/C2; Goethe C1; ÖSD C2 or German FSP section. Eligible German-language school qualifications can substitute. English IELTS does not establish this requirement.','DSH 2; TestDaF TDN4 во всех частях; DSD II; telc C1 Hochschule/C2; Goethe C1; ÖSD C2 либо немецкая часть FSP. Могут подойти соответствующие немецкоязычные школьные квалификации. Английский IELTS не подтверждает это требование.')}],documents=[L('Apply through uni-assist with school records, German CV, language proof and TestAS. Eligibility equivalent to EU applicants uses a different procedure; indirect HZB and medicine also have separate routes.','Заявка через uni-assist со школьными документами, немецким CV, языковым подтверждением и TestAS. Категории, приравненные к ЕС, используют другую процедуру; у косвенного HZB и медицины также отдельные маршруты.')],sources=[s(u,'Cologne non-EU direct-HZB undergraduate procedure','Köln: бакалаврская процедура вне ЕС с прямым HZB')])],'Made German and TestAS requirements visible with applicant-category exceptions; IELTS cannot substitute for German.')

u='https://www.th-deg.de/ain-b-en'
save('deggendorf-institute-of-technology',[route(id='artificial-intelligence-english',label=L('Artificial Intelligence BSc — English, Deggendorf campus','Artificial Intelligence BSc — английский, кампус Deggendorf'),programmeIds=['computer-science','data-science'],english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':None},'alternatives':L('English CEFR B2 is required. The linked official language table lists accepted certificate categories; a single overall IELTS cutoff is not inferred from a component-range table.','Требуется английский CEFR B2. Связанная официальная языковая таблица перечисляет категории сертификатов; единый overall IELTS не выводится из таблицы диапазонов секций.')},academic={'satPolicy':'unknown','note':L('A recognised entrance qualification plus the programme admission test is required: advanced-school mathematics, logic/computer science multiple choice and a 200–300-word essay. No SAT/ACT substitution is established.','Нужны признанная квалификация допуска и тест программы: школьная математика повышенного уровня, задания с выбором по логике/информатике и эссе 200–300 слов. Замена SAT/ACT не установлена.')},localLanguage=[{'name':'German during the degree','requirement':L('German A2 must be demonstrated by the end of studies; this is not the English-route admission minimum.','Немецкий A2 нужно подтвердить к окончанию обучения; это не вступительный минимум английского маршрута.')}],sources=[s(u,'DIT English Artificial Intelligence bachelor: entry and language conditions','DIT: английский бакалавриат Artificial Intelligence, допуск и языки')])],'Distinguished the English AI degree, actual admission test and later German A2 from German-language AI and graduate degrees.', ['Fall 2027 cycle, precise certificate table row/section mapping and applicant-specific waiver remain to be confirmed.'])
